remarks.code:
function func_name(param1 : type1; param2 : type2) return return_type is
    -- local declarations
begin
    -- statements
    return expression;
end func_name;

function add(a, b : integer) return integer;
procedure swap(variable x, y : inout integer);
function to_vector(val : integer; size : natural) return std_logic_vector;

-- Enumeration
type state_t is (IDLE, RUNNING, STOPPED);

-- Array (constrained)
type memory_t is array (0 to 1023) of std_logic_vector(7 downto 0);

-- Array (unconstrained) - partially supported
type data_array is array (natural range <>) of std_logic_vector(7 downto 0);

-- Record
type packet_t is record
    valid : std_logic;
    data  : std_logic_vector(31 downto 0);
end record;

-- Subtype
subtype byte is std_logic_vector(7 downto 0);

case selector is
    when "0000" => statements;
    when "0001" | "0010" => statements;  -- Multiple choices
    when others => statements;           -- Default branch
end case;

target <= value1 when cond1 else
          value2 when cond2 else
          default_value;

-- Ascending loop
for i in 0 to 7 loop
    statements;
end loop;

-- Descending loop
for i in 7 downto 0 loop
    statements;
end loop;

-- Loop with expression ranges
for i in 0 to ARRAY_SIZE - 1 loop
    statements;
end loop;

-- For-generate (iterative)
label : for i in 0 to 7 generate
    signal_name(i) <= some_expression;
end generate [label];

-- If-generate (conditional)
label : if CONDITION generate
    -- statements
end generate [label];

if condition1 then
    statements;
elsif condition2 then
    statements;
else
    statements;
end if;

return;              -- Return from procedure (no value)
return expression;   -- Return from function with value
return a + b;        -- Return computed value from function

-- Simple infinite loop with conditional exit
loop
    read_data;
    exit when buffer_full = '1';
end loop;

-- Loop with unconditional exit
loop
    process_item;
    if done then
        exit;
    end if;
end loop;

-- Loop with multiple exit conditions
loop
    compute;
    exit when error = '1';
    exit when complete = '1';
end loop;

-- Simple while loop
while count < 10 loop
    count := count + 1;
end loop;

-- While loop with complex condition
while (enable = '1') and (error = '0') loop
    process_data;
end loop;

-- While loop with exit
while true loop
    statements;
    exit when done = '1';
end loop;

member.summary:
Skips a component instantiation statement.
Handles the pattern: label : ComponentName [generic map (...)] port map (...) ;
Added in v0.13.0 to support component instantiation syntax.

remarks.code:
// Subscribe to progress updates
ProgressReporter.Instance.ProgressChanged += (sender, e) =>
{
    var (progress, message) = e.Update.ToTuple();
    Console.WriteLine($"{progress:P0} - {message}");
};

// Report progress from anywhere
ProgressReporter.Instance.Report(0.5f, "Parsing architecture", ProcessingPhase.ParsingArchitecture);

member.summary:
Parses an alias declaration and registers the alias name as a Variable
so later references resolve correctly. Supports the common forms:
  alias name is target(range);
  alias name : subtype is target(range);
